#!/usr/bin/env python3
# Some portions generated by Codex.
import pathlib,json
p=pathlib.Path(__file__).resolve().parent;arms=['base','stack','ordered','both'];ss={a:json.loads((p/'runs'/('profile-'+a)/'profile-summary.json').read_text()) for a in arms}
o=['# Ordered adapter: separate actual HTTP profiles','','Four fresh JVMs, 60 warmups then 30 recorded requests per arm. All 360 requests passed witnesses. Full128-frame recording/export; every Java stack analyzed for route predicates. Node CPU absent; setup/metrics between requests included. No diagnostic duration pooled with clean timing.','','| Arm | Java samples | Ordered route stack samples | Legacy adapter map stack samples | Ordered + map samples | Binding nearest | NDJSON nearest |','|---|---:|---:|---:|---:|---:|---:|']
for a,s in ss.items():
 r=s['actualAdapterRouteSamples'];o.append(f"| {a} | {s['javaSamples']} | {r.get('orderedAdapterStackSamples',0)} | {r.get('legacyMapRoundtripStackSamples',0)} | {r.get('orderedStackWithQueryBindingSetSamples',0)} | {s['nearestCategories'].get('snapshot_binding',0)} | {s['nearestCategories'].get('workbench_ndjson',0)} |")
o+=['','Ordered route is the per-sample union of TupleResultBuilder.queryResultValues and WorkbenchPageResultWriter.tryOrderedQueryValues frames. Legacy map requires TupleResultBuilder.result plus QueryBindingSet get/add/set frames. Each predicate counts a sample once, not once per matching frame. Predicates and nearest categories may overlap and must not be added. Zero sampled frames is not proof of zero invocations; positive candidate samples prove actual route execution without timing counters.','','## Interpretation','','The bounded adapter skips reconstructing a QueryBindingSet and reading it by name, preserving complete source lookup before term packing and the fallback path. Broad binding categories include native materialization, snapshot transport and binary writer lookup, not just this adapter. Never assign the whole category or its change to the bypass. Actual route proof is necessary but cannot establish an incremental speedup. Clean both/stack gain was inconclusive; the existing stack already explains most of the favorable combined/base result within this series.','','First-row signs and late-fork drift remain important. Do not turn one profile per arm into a causal allocation/GC story. Sampled allocation weights are neither exact allocated bytes nor retained heap. Pinned Jackson uses a concurrent-deque recycler by default, not ThreadLocal; fresh-generator setup is not a TLS optimization. No candidate adoption or extra clean measurement round follows automatically.','','## Nearest categories and top adapter stacks','']
for a,s in ss.items():
 o+=['### '+a,'',json.dumps(s['nearestCategories'],sort_keys=True),'']
 hits=[(k,n) for k,n in s['topStacks'] if 'queryResultValues' in k or 'tryOrderedQueryValues' in k or ('TupleResultBuilder.result' in k and 'QueryBindingSet' in k)]
 for k,n in hits[:3]:o.append(f'- {n} samples: `{k}`.')
 o.append('')
(p/'HTTP-PROFILES.md').write_text('\n'.join(o).replace('Full128','Full 128'))
